from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import urljoin, urlsplit
import hashlib
import json

root = Path('products/services/uk-contracts-finder-data-qa')
raw = (root / 'raw/search-data-validation.html').read_bytes()
source = 'https://www.contractsfinder.service.gov.uk/Search/Results?Keywords=data%20validation'
expected_hash = '6b14593a38c224322346f454c0d92cc5227dd96cfb5e1b2efb5c8be2a4026a80'
actual_hash = hashlib.sha256(raw).hexdigest()
if actual_hash != expected_hash:
    raise SystemExit('Capture hash does not match the FETCH receipt')

class SearchPage(HTMLParser):
    def __init__(self):
        super().__init__()
        self.notice = None
        self.parts = []
        self.links = {}

    def handle_starttag(self, tag, attrs):
        if tag != 'a':
            return
        href = dict(attrs).get('href') or ''
        url = urlsplit(urljoin(source, href))
        self.notice = None
        self.parts = []
        if url.scheme == 'https' and url.netloc == urlsplit(source).netloc and url.path.lower().startswith('/notice/'):
            self.notice = url._replace(fragment='').geturl()

    def handle_data(self, data):
        if self.notice:
            self.parts.append(data)

    def handle_endtag(self, tag):
        if tag == 'a' and self.notice:
            label = ' '.join(' '.join(self.parts).split())
            if label or self.notice not in self.links:
                self.links[self.notice] = label[:300]
            self.notice = None

page = SearchPage()
page.feed(raw.decode('utf-8', errors='replace'))
page.close()
result = {'source': source, 'capture_receipt': 'TASK-179509861201', 'sha256': actual_hash, 'scope': 'One saved search page. Link text is a discovery lead only. No deadline, paid scope, eligibility or submission route verified.', 'notice_links': [{'url': url, 'label': label} for url, label in page.links.items()]}
artifact = root / 'search-notice-links.json'
artifact.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(artifact.read_text(encoding='utf-8'))
